/* conn.h - public API */
typedef struct Conn Conn;            /* incomplete type: size and layout hidden */
Conn *conn_open(const char *addr);   /* factory: the only way to obtain one */
void  conn_send(Conn *c, const void *buf, size_t n);
void  conn_destroy(Conn *c);         /* ownership is released here */

/* conn.c - private implementation */
struct Conn { int fd; size_t used; };   /* copy by value is impossible outside */
